import { afterEach, beforeEach, expect, test, vi } from 'vitest';
import { render, type RenderResult } from 'vitest-browser-react';

import Gallery from './Gallery.tsx';

let screen: RenderResult;

beforeEach(() => {
  const exampleWoodlandsResponse = JSON.stringify({
    "1": "",
    "2": "",
    "3": ""
  });
  const exampleTuasResponse = JSON.stringify({
    "1": "",
    "2": "",
    "3": ""
  });

  vi.spyOn(globalThis, 'fetch').mockImplementation(async (url) => {
    if (typeof url !== 'string' || (
      !url.includes('woodlands') && !url.includes('tuas')
    )) throw new Error(`Unexpected URL: ${typeof url === 'object' ? JSON.stringify(url) : url}`);

    if (url === 'woodlands') return new Response(exampleWoodlandsResponse);
    else return new Response(exampleTuasResponse);
  });
});

afterEach(() => {
  vi.restoreAllMocks();
});

test('renders location selector', async () => {
  screen = await render(<Gallery />);

  await expect.element(screen.getByRole('button', { name: /woodlands/i })).toBeVisible();
  await expect.element(screen.getByRole('button', { name: /tuas/i })).toBeVisible();
});

test('loads checkpoint images', async () => {
  const expectedCaption = 'Woodlands causeway';

  screen = await render(<Gallery />);

  await expect.element(screen.getByRole('img', { name: expectedCaption })).toBeVisible();
  await expect.element(screen.getByText(expectedCaption)).toBeVisible();
});

test('switches location', async () => {
  const expectedCaption = 'After Tuas West Road';

  screen = await render(<Gallery />);
  await screen.getByRole('button', { name: /tuas/i }).click();

  await expect.element(screen.getByRole('img', { name: expectedCaption })).toBeVisible();
  await expect.element(screen.getByText(expectedCaption)).toBeVisible();
});

test('displays error message when images fail to load', async () => {
  const expectedErrorHeading = 'Could not load images';
  vi.spyOn(globalThis, 'fetch').mockRejectedValue('Not a real error');

  screen = await render(<Gallery />);

  await expect.element(screen.getByRole('heading', { name: expectedErrorHeading })).toBeVisible();
});
